result = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=100.0 * COUNT(transactions_made.WHERE(status == "SUCCESS")) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

result = Broker.CALCULATE(
    num_customers_faang = COUNT(
        Customers.WHERE(
            ENDSWITH(email, ".com") & 
            HAS(
                transactions_made.WHERE(
                    (transaction_type == "BUY") &
                    (ISIN(ticker.symbol, ("AMZN", "AAPL", "GOOGL", "META", "NFLX")))
                )
            ) == 1
        )
    )
)

result = Customers.WHERE(
    (join_date >= "2023-01-01") & (status == "active")
).PARTITION(
    name="countries", by=country
).CALCULATE(
    country=country,
    count=COUNT(Customers)
)

result = Customers.WHERE(country == "USA").CALCULATE(
    num_transactions = COUNT(
        transactions_made.WHERE(
            (date_time >= DATETIME('now', 'start of week', '-7 days')) &
            (date_time < DATETIME('now', 'start of week'))
        )
    ),
    total_amount = SUM(
        transactions_made.WHERE(
            (date_time >= DATETIME('now', 'start of week', '-7 days')) &
            (date_time < DATETIME('now', 'start of week'))
        ).amount
    )
)

result = Broker.CALCULATE(
    num_customers = COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Customers.WHERE(
    HASNOT(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    customer_name=name
)

result = Customers.WHERE(
    HAS(transactions_made.WHERE(transaction_type == 'buy')) == 1
).CALCULATE(
    customer_id=_id
)

result = DailyPrices.WHERE(
    date >= "2023-04-01"
).PARTITION(name="tickers", by=ticker_id).CALCULATE(
    ticker_id
)

result = Broker.CALCULATE(
    lowest_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == "VTI") & 
            (DATEDIFF("days", date, DATETIME("now")) <= 7)
        ).close
    )
)

result = Broker.CALCULATE(
    num_transactions = COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME('now')) <= 70
        ).transactions_made
    )
)

result = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    days_to_first_transaction=DATEDIFF(
        "days", 
        join_date, 
        MIN(transactions_made.date_time)
    )
)

result = Customers.CALCULATE(
    customer_id=_id,
    customer_name=name,
    num_sell_transactions=COUNT(
        transactions_made.WHERE(
            (DATE(date_time) == "2023-04-01") & 
            (transaction_type == "sell")
        )
    )
).TOP_K(1, by=num_sell_transactions.DESC())

result = Salespersons.CALCULATE(
    salesperson_id=_id,
    first_name=first_name,
    last_name=last_name,
    num_sales=COUNT(
        sales_made.WHERE(
            DATEDIFF("days", sale_date, DATETIME("now")) <= 30
        )
    )
).ORDER_BY(num_sales.DESC())

result = Dealership.CALCULATE(
    number_of_sales=COUNT(
        Sales.WHERE(
            (DATEDIFF("days", sale_date, DATETIME("now")) <= 30) &
            (DATEDIFF("days", sale_date, DATETIME("now")) >= 0) &
            (car.make == "Toyota")
        )
    ),
    total_revenue=SUM(
        Sales.WHERE(
            (DATEDIFF("days", sale_date, DATETIME("now")) <= 30) &
            (DATEDIFF("days", sale_date, DATETIME("now")) >= 0) &
            (car.make == "Toyota")
        ).sale_price
    )
)
